"""Find the stretches of opening hours nobody covers."""

from typing import Iterable, List
from hourglass.parsing import format_span
from hourglass.models import Span
from hourglass.merging import merge_spans
from hourglass.errors import ProjectError

class OutsideHoursError(ProjectError):
    """A worked span reaches outside opening hours."""

def outside(span: Span, opening: Span) -> bool:
    early = span.start < opening.start
    return early or span.end > opening.end

def check_inside(
    worked: Iterable[Span], opening: Span
):
    for span in worked:
        if outside(span, opening):
            raise OutsideHoursError(
                f"{format_span(span)} is outside "
                f"{format_span(opening)}"
            )

def format_gap(span: Span) -> str:
    return f"gap {format_span(span)} ({span.minutes} min)"

def gap_spans(
    merged: List[Span], opening: Span
) -> List[Span]:
    edges = [opening.start]
    for item in merged:
        edges += [item.start, item.end]
    edges.append(opening.end)
    pairs = zip(edges[::2], edges[1::2])
    return [
        Span(low, high) for low, high in pairs if low < high
    ]

# ---
def find_gaps(
    worked: Iterable[Span], opening: Span
) -> List[str]:
    """Labels for uncovered stretches; raises if outside."""
    worked = list(worked)
    check_inside(worked, opening)
    found = gap_spans(merge_spans(worked), opening)
    return [format_gap(item) for item in found]
